persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers a report on a company and requests that recipients take action by watching the trade on Monday. This implies a reciprocal relationship where they receive information and must provide an action in return."},
    "Scarcity": {"Explanation": "The email creates a sense of urgency by mentioning that it is 'time to act' and refers to a specific day (Monday) when the trade should be watched, implying a limited time frame."},
    "Authority": {"Explanation": "The email does not explicitly claim authority from a recognized institution, title, or role. There is no mention of any credible sources or experts."},
    "Commitment/Consistency": {"Explanation": "The email does not reference prior behavior or choices to push for further action. There is no indication that the recipients have previously engaged with the company or made similar decisions."},
    "Liking": {"Explanation": "The email does not use familiarity, flattery, or personalization to build trust or rapport. It is impersonal and focuses on the potential profitability of the stock rather than building a personal connection."},
    "Social proof": {"Explanation": "The email does not reference other people's participation or endorsement. There is no mention of others who have taken action or benefited from the stock recommendation."}
}

