persuasion_principles:
{
    "Reciprocity": {"Explanation": "The email offers a survey participation as a way to receive recognition and feedback, implying that by participating, the recipient will gain insight into Enron's standing and their own workplace experience."},
    "Scarcity": {"Explanation": "The email implies urgency by mentioning that only 250 surveys were sent out and encouraging quick action to check the mailbox, though it does not explicitly mention a deadline or limited availability."},
    "Authority": {"Explanation": "The email references Enron's achievements and rankings from Fortune magazine, which can lend authority and credibility to the request for participation in the survey."},
    "Commitment/Consistency": {"Explanation": "The email references Enron's past achievements and its goal to improve its ranking, suggesting a commitment to being a top company and encouraging the reader to contribute to this consistency."},
    "Liking": {"Explanation": "The email uses positive language and acknowledges the reader's contributions, building a sense of liking and appreciation for their hard work at Enron."},
    "Social proof": {"Explanation": "The email references Enron's high rankings and achievements, which serve as social proof of the company's excellence and the value of participating in the survey."}
}

